import {drawingFont} from './vendor/drawing-font.js';
const encoder=new TextEncoder(),num=n=>{if(!Number.isFinite(n))throw Error('Drawing contains a non-finite coordinate.');return String(+n.toFixed(4));};
export const xml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function textWidth(text,size=3){return [...String(text)].reduce((n,c)=>n+(drawingFont.glyphs[c.codePointAt(0)]||drawingFont.glyphs[63])[1],0)*size/1000;}
export function fitText(text,width,size=3){let s=String(text??'');if(textWidth(s,size)<=width)return s;while(s&&textWidth(s+'…',size)>width)s=s.slice(0,-1);return s+'…';}
export function wrapText(text,width,size=3){const out=[];for(const para of String(text??'').split('\n')){let line='';for(const word of para.split(/\s+/)){if(line&&textWidth(line+' '+word,size)>width){out.push(line);line='';}if(textWidth(word,size)>width){if(line){out.push(line);line='';}let chunk='';for(const c of word){if(textWidth(chunk+c,size)>width){out.push(chunk);chunk='';}chunk+=c;}line=chunk;}else line+=(line?' ':'')+word;}out.push(line);}return out;}
export function drawingSVG(sheet){
 const paths=sheet.commands.map(c=>{const stroke=c.stroke||'#273c36',dash=c.dash?' stroke-dasharray="'+c.dash.join(' ')+'"':'';
  if(c.type==='raster')return `<image x="${num(c.x)}" y="${num(c.y)}" width="${num(c.w)}" height="${num(c.h)}" href="${c.png}"/>`;
  if(c.type==='path')return `<path d="${c.points.map((p,i)=>(i?'L':'M')+p.map(num).join(' ')).join(' ')}${c.close?' Z':''}" fill="${c.fill||'none'}" stroke="${c.stroke===false?'none':stroke}" stroke-width="${c.width||.2}"${dash}/>`;
  if(c.type==='circle')return `<circle cx="${num(c.x)}" cy="${num(c.y)}" r="${num(c.r)}" fill="${c.fill||'#fff'}" stroke="${stroke}" stroke-width="${c.width||.2}"/>`;
  if(c.type==='text')return `<text x="${num(c.x)}" y="${num(c.y)}" font-size="${c.size}" fill="${c.color||stroke}" text-anchor="${c.align==='center'?'middle':c.align==='right'?'end':'start'}"${c.rotate?` transform="rotate(${c.rotate} ${num(c.x)} ${num(c.y)})"`:''} textLength="${num(textWidth(c.text,c.size))}" lengthAdjust="spacingAndGlyphs">${xml(c.text)}</text>`;
  return '';
 }).join('');
 return `<?xml version="1.0" encoding="UTF-8"?><svg xmlns="http://www.w3.org/2000/svg" width="${sheet.w}mm" height="${sheet.h}mm" viewBox="0 0 ${sheet.w} ${sheet.h}"><title>${xml(sheet.title)}</title><desc>${xml(sheet.description||'MOCKUPBENCH engineering drawing. Nominal model dimensions.')}</desc><rect width="100%" height="100%" fill="white"/><g font-family="DejaVu Sans,Arial,sans-serif" stroke-linecap="round" stroke-linejoin="round">${paths}</g></svg>`;
}
const concat=chunks=>{const out=new Uint8Array(chunks.reduce((s,c)=>s+c.length,0));let i=0;for(const c of chunks){out.set(c,i);i+=c.length;}return out;};
const bytes=s=>encoder.encode(s);
const rgb=hex=>{let str=hex.replace('#','');if(str.length===3)str=[...str].map(c=>c+c).join('');const n=parseInt(str,16);return [(n>>16&255)/255,(n>>8&255)/255,(n&255)/255].map(num).join(' ');};
export async function loadDrawingFont(signal){const r=await fetch(new URL('./vendor/drawing-font.ttf',import.meta.url),{signal});if(!r.ok)throw Error('Drawing font could not load. Reload the complete app package.');return new Uint8Array(await r.arrayBuffer());}
// Vector PDF with an embedded TrueType CID font and ToUnicode mapping (ISO 32000-1, 9.7/9.10).
export function drawingPDF(sheets,fontBytes){
 if(!sheets.length||!fontBytes?.length)throw Error('Drawing sheets and font are required.');
 const objects=[null],reserve=()=>{objects.push(null);return objects.length-1;},put=(id,s)=>objects[id]=typeof s==='string'?bytes(s):s,add=s=>{const id=reserve();put(id,s);return id;};
 const stream=(data,extra='')=>concat([bytes(`<< /Length ${data.length} ${extra} >>\nstream\n`),data,bytes('\nendstream')]);
 const catalog=reserve(),pagesId=reserve(),fontId=reserve(),descId=reserve(),used=new Map();
 function hexText(s){let out='';for(const c of String(s)){const cp=c.codePointAt(0),entry=drawingFont.glyphs[cp]||drawingFont.glyphs[63];used.set(entry[0],{cp:drawingFont.glyphs[cp]?cp:63,width:entry[1]});out+=entry[0].toString(16).padStart(4,'0');}return out;}
 const pageIds=[];
 for(const sheet of sheets){const images=[];const commands=['q','2.83464567 0 0 -2.83464567 0 '+num(sheet.h*72/25.4)+' cm','1 J 1 j'];
  for(const c of sheet.commands){
   if(c.type==='raster'){if(!c.compressed)throw Error('Drawing images have not been prepared.');const name='Im'+images.length,id=add(stream(c.compressed,`/Type /XObject /Subtype /Image /Width ${c.imageW} /Height ${c.imageH} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /FlateDecode`));images.push({name,id});commands.push(`q ${num(c.w)} 0 0 ${num(-c.h)} ${num(c.x)} ${num(c.y+c.h)} cm /${name} Do Q`);continue;}
   if(c.type==='text'){const w=textWidth(c.text,c.size),offset=c.align==='center'?-w/2:c.align==='right'?-w:0,angle=(c.rotate||0)*Math.PI/180,cos=Math.cos(angle),sin=Math.sin(angle);commands.push(`q ${rgb(c.color||'#273c36')} rg ${num(cos)} ${num(sin)} ${num(-sin)} ${num(cos)} ${num(c.x)} ${num(c.y)} cm BT /F1 ${num(c.size)} Tf 1 0 0 -1 ${num(offset)} 0 Tm <${hexText(c.text)}> Tj ET Q`);continue;}
   commands.push(`${num(c.width||.2)} w ${rgb(c.stroke||'#273c36')} RG ${c.fill?rgb(c.fill):'1 1 1'} rg [${(c.dash||[]).map(num).join(' ')}] 0 d`);
   if(c.type==='path'){commands.push(c.points.map((p,i)=>p.map(num).join(' ')+(i?' l':' m')).join(' ')+(c.close?' h':'')+(c.fill?(c.stroke===false?' f':' B'):' S'));}
   if(c.type==='circle'){const {x,y,r}=c,k=r*.55228475;commands.push(`${num(x+r)} ${num(y)} m ${num(x+r)} ${num(y+k)} ${num(x+k)} ${num(y+r)} ${num(x)} ${num(y+r)} c ${num(x-k)} ${num(y+r)} ${num(x-r)} ${num(y+k)} ${num(x-r)} ${num(y)} c ${num(x-r)} ${num(y-k)} ${num(x-k)} ${num(y-r)} ${num(x)} ${num(y-r)} c ${num(x+k)} ${num(y-r)} ${num(x+r)} ${num(y-k)} ${num(x+r)} ${num(y)} c B`);}
  }
  commands.push('Q');const content=add(stream(bytes(commands.join('\n')))),page=add(`<< /Type /Page /Parent ${pagesId} 0 R /MediaBox [0 0 ${num(sheet.w*72/25.4)} ${num(sheet.h*72/25.4)}] /Resources << /Font << /F1 ${fontId} 0 R >> /XObject << ${images.map(o=>`/${o.name} ${o.id} 0 R`).join(' ')} >> >> /Contents ${content} 0 R >>`);pageIds.push(page);
 }
 const cmap=[...used].sort((a,b)=>a[0]-b[0]),chunks=[];for(let i=0;i<cmap.length;i+=100){const group=cmap.slice(i,i+100);chunks.push(group.length+' beginbfchar\n'+group.map(([gid,{cp}])=>'<'+gid.toString(16).padStart(4,'0')+'> <'+cp.toString(16).padStart(4,'0')+'>').join('\n')+'\nendbfchar');}
 const mapId=add(stream(bytes('/CIDInit /ProcSet findresource begin 12 dict begin begincmap /CIDSystemInfo << /Registry (Adobe) /Ordering (UCS) /Supplement 0 >> def /CMapName /DrawingUnicode def /CMapType 2 def 1 begincodespacerange <0000> <FFFF> endcodespacerange\n'+chunks.join('\n')+'\nendcmap CMapName currentdict /CMap defineresource pop end end'))),fileId=add(stream(fontBytes,`/Length1 ${fontBytes.length}`));
 put(descId,`<< /Type /FontDescriptor /FontName /DejaVuSans /Flags 32 /FontBBox [${drawingFont.bbox.join(' ')}] /ItalicAngle 0 /Ascent ${drawingFont.ascent} /Descent ${drawingFont.descent} /CapHeight 730 /StemV 80 /FontFile2 ${fileId} 0 R >>`);
 const cid=add(`<< /Type /Font /Subtype /CIDFontType2 /BaseFont /DejaVuSans /CIDSystemInfo << /Registry (Adobe) /Ordering (Identity) /Supplement 0 >> /FontDescriptor ${descId} 0 R /CIDToGIDMap /Identity /DW 600 /W [${cmap.map(([id,v])=>id+' ['+v.width+']').join(' ')}] >>`);
 put(fontId,`<< /Type /Font /Subtype /Type0 /BaseFont /DejaVuSans /Encoding /Identity-H /DescendantFonts [${cid} 0 R] /ToUnicode ${mapId} 0 R >>`);put(pagesId,`<< /Type /Pages /Count ${pageIds.length} /Kids [${pageIds.map(n=>n+' 0 R').join(' ')}] >>`);put(catalog,`<< /Type /Catalog /Pages ${pagesId} 0 R >>`);
 const out=[bytes('%PDF-1.4\n%MOCKUPBENCH\n')],offsets=[0];let offset=out[0].length;objects.slice(1).forEach((o,i)=>{offsets.push(offset);const chunk=concat([bytes(`${i+1} 0 obj\n`),o,bytes('\nendobj\n')]);out.push(chunk);offset+=chunk.length;});out.push(bytes(`xref\n0 ${objects.length}\n0000000000 65535 f \n${offsets.slice(1).map(n=>String(n).padStart(10,'0')+' 00000 n ').join('\n')}\ntrailer\n<< /Size ${objects.length} /Root ${catalog} 0 R >>\nstartxref\n${offset}\n%%EOF\n`));return concat(out);
}
const crcTable=Uint32Array.from({length:256},(_,n)=>{for(let k=0;k<8;k++)n=n&1?0xedb88320^(n>>>1):n>>>1;return n>>>0;});
const crc32=data=>{let n=0xffffffff;for(const b of data)n=crcTable[(n^b)&255]^(n>>>8);return (n^0xffffffff)>>>0;};
export function drawingZIP(files){const local=[],central=[];let offset=0;for(const [name,content] of files){const data=typeof content==='string'?bytes(content):content,filename=bytes(name),crc=crc32(data),header=new Uint8Array(30),v=new DataView(header.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint16(12,33,true);v.setUint32(14,crc,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,filename.length,true);local.push(header,filename,data);const c=new Uint8Array(46),d=new DataView(c.buffer);d.setUint32(0,0x02014b50,true);d.setUint16(4,20,true);d.setUint16(6,20,true);d.setUint16(8,0x800,true);d.setUint16(14,33,true);d.setUint32(16,crc,true);d.setUint32(20,data.length,true);d.setUint32(24,data.length,true);d.setUint16(28,filename.length,true);d.setUint32(42,offset,true);central.push(c,filename);offset+=header.length+filename.length+data.length;}const directory=concat(central),end=new Uint8Array(22),e=new DataView(end.buffer);e.setUint32(0,0x06054b50,true);e.setUint16(8,files.length,true);e.setUint16(10,files.length,true);e.setUint32(12,directory.length,true);e.setUint32(16,offset,true);return concat([...local,directory,end]);}

async function deflate(data){if(typeof CompressionStream==='undefined')throw Error('This browser needs CompressionStream support for drawing export. Use a current browser.');return new Uint8Array(await new Response(new Blob([data]).stream().pipeThrough(new CompressionStream('deflate'))).arrayBuffer());}
function pngChunk(type,data){const tag=bytes(type),out=new Uint8Array(data.length+12),v=new DataView(out.buffer);v.setUint32(0,data.length);out.set(tag,4);out.set(data,8);v.setUint32(data.length+8,crc32(concat([tag,data])));return out;}
export async function prepareDrawingImages(sheets,signal){for(const sheet of sheets)for(const c of sheet.commands){signal?.throwIfAborted();if(c.type!=='raster'||c.png)continue;c.compressed=await deflate(c.pixels);const rows=new Uint8Array((c.imageW*3+1)*c.imageH);for(let y=0;y<c.imageH;y++)rows.set(c.pixels.subarray(y*c.imageW*3,(y+1)*c.imageW*3),y*(c.imageW*3+1)+1);const header=new Uint8Array(13),v=new DataView(header.buffer);v.setUint32(0,c.imageW);v.setUint32(4,c.imageH);header[8]=8;header[9]=2;const png=concat([new Uint8Array([137,80,78,71,13,10,26,10]),pngChunk('IHDR',header),pngChunk('IDAT',await deflate(rows)),pngChunk('IEND',new Uint8Array())]);let binary='';for(let i=0;i<png.length;i+=8192)binary+=String.fromCharCode(...png.subarray(i,i+8192));c.png='data:image/png;base64,'+btoa(binary);delete c.pixels;}}
